"""Reviewed fleet-only delta used by historical workflow pin tests."""
GUARD = '      - name: Guard fleet hosted-only profile\n        if: inputs.repo == \'bean-fleet\'\n        env:\n          GATE_REPO: ${{ github.repository }}\n          GATE_EVENT: ${{ github.event_name }}\n          GATE_RUNNER: ${{ inputs.runner }}\n          GATE_FULL: ${{ inputs.full }}\n        shell: bash\n        run: |\n          set -euo pipefail\n          test "$GATE_REPO" = \'stevekkall-beansgc/bean-fleet\'\n          test "$GATE_RUNNER" = \'macos-15\'\n          test "${RUNNER_ENVIRONMENT:-}" = \'github-hosted\'\n          test "${RUNNER_OS:-}" = \'macOS\'\n          test "$GATE_FULL" = \'true\'\n          case "$GATE_EVENT" in push|pull_request) ;; *) exit 1 ;; esac\n'
SETUP = '      - name: Verify fleet vendor and install hash-pinned public dependencies\n        if: inputs.repo == \'bean-fleet\'\n        shell: bash\n        run: |\n          set -euo pipefail\n          test "$(uname -m)" = arm64\n          python3 -c \'import sys; assert sys.version_info[:2] == (3,14)\'\n          python3 - <<\'PYCODE\'\n          import hashlib,json,pathlib\n          root=pathlib.Path(\'caller\')\n          if root.is_symlink() or (root/\'release\').is_symlink() or (root/\'vendor\').is_symlink(): raise SystemExit(\'unsafe source path\')\n          def read_regular(path):\n              if path.is_symlink() or not path.is_file(): raise SystemExit(\'unsafe vendor path\')\n              return path.read_bytes()\n          manifest=read_regular(root/\'release/VENDORED-COMMONS.json\')\n          if hashlib.sha256(manifest).hexdigest()!=\'7fa61859d3a7c032555c921f5e16c1ba9ecd58adb93316c22eb2fed97795b524\': raise SystemExit(\'vendor manifest mismatch\')\n          requirements=read_regular(root/\'release/build-requirements.txt\')\n          if hashlib.sha256(requirements).hexdigest()!=\'6f8869592f6bb6e788c4d82813d4c7a3f2cb3f630a8715345174fdb37e0142c0\': raise SystemExit(\'dependency lock mismatch\')\n          record=json.loads(manifest)\n          if record[\'commit\']!=\'e1ca435f2d64bf694f4d81b6828dfff537e8afef\': raise SystemExit(\'vendor revision mismatch\')\n          vendor=root/\'vendor/bean-commons\'\n          if vendor.is_symlink() or not vendor.is_dir(): raise SystemExit(\'unsafe vendor root\')\n          files={}\n          for path in vendor.rglob(\'*\'):\n              if path.is_symlink(): raise SystemExit(\'vendor symlink denied\')\n              if path.is_file(): files[path.relative_to(vendor).as_posix()]=hashlib.sha256(path.read_bytes()).hexdigest()\n          if files!=record[\'files\']: raise SystemExit(\'vendor inventory mismatch\')\n          PYCODE\n          python3 -m pip install --require-hashes --only-binary=:all: -r caller/release/build-requirements.txt\n'
def before_fleet(workflow):
    replacements = ((GUARD, ''), (SETUP, ''),
        ("inputs.repo == 'bean-fleet' && 'v0.7.11' || ", ''),
        ("(inputs.repo == 'beanlabs' || inputs.repo == 'bean-fleet') && '3.14'", "inputs.repo == 'beanlabs' && '3.14'"),
        ("inputs.repo == 'bean-fleet' || inputs.repo == 'agency'", "inputs.repo == 'agency'"))
    for actual, old in replacements:
        if workflow.count(actual) != 1: raise AssertionError('fleet delta changed')
        workflow=workflow.replace(actual,old,1)
    return workflow
